int stubs_resolve(HMODULE real) {
    int missing = 0;
    for (int i = 0; i < STUB_COUNT; i++) {
        stub_ptrs[i] = (void *)GetProcAddress(real, stub_names[i]);
        if (!stub_ptrs[i]) missing++;
    }
    return missing;
}
